/* Cmd+K / Ctrl+K command palette for sites.maniarnamra.com.
 * Searches /search-index.json (generated by .github/scripts/update-listings.py)
 * plus a few fixed links and theme commands. No dependencies.
 * Colours come from the page's CSS tokens (--bg, --fg, --muted, --rule,
 * --line, --hover, --accent) with light fallbacks, so it works on any page. */
(() => {
  'use strict';
  const d = document;
  const root = d.documentElement;
  if (root.dataset.cmdk) return;
  root.dataset.cmdk = '1';

  const THEME_KEY = 'theme';
  const isMac = /Mac|iPhone|iPad|iPod/i.test(
    (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || navigator.userAgent
  );
  const SECTIONS = { research: 'Report', learning: 'Guide' };
  const LINKS = [
    { group: 'Go to', title: 'Home', url: '/' },
    { group: 'Go to', title: 'Research', desc: 'All reports', url: '/research/' },
    { group: 'Go to', title: 'Learning', desc: 'All guides', url: '/learning/' },
    { group: 'Go to', title: 'llms.txt', desc: 'How agents add pages here', url: '/llms.txt' },
    { group: 'Go to', title: 'maniarnamra.com', desc: 'Who Namra Maniar is', url: 'https://maniarnamra.com' },
  ];

  const css = `
.cmdk-ready .cmdk-trigger{visibility:visible}
.cmdk-trigger{display:inline-flex;align-items:center;gap:.5rem;font:inherit;font-size:.875rem;line-height:1.4;color:var(--muted,#555);background:transparent;border:1px solid var(--line,#ddd);border-radius:.25rem;padding:.2rem .3rem .2rem .6rem;cursor:pointer}
.cmdk-trigger:hover{color:var(--fg,#111);border-color:var(--accent,#111)}
.cmdk-trigger:focus-visible{outline:2px solid var(--accent,#111);outline-offset:2px}
.cmdk-trigger kbd,.cmdk kbd{font:.75rem/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--muted,#555);border:1px solid var(--line,#ddd);border-radius:.2rem;padding:0 .3rem}
.cmdk{padding:0;margin:12vh auto auto;width:min(36rem,calc(100% - 2rem));max-height:min(70vh,32rem);border:1px solid var(--rule,#111);background:var(--bg,#fff);color:var(--fg,#111);font:1rem/1.5 Georgia,'Times New Roman',serif;box-shadow:0 1rem 3rem rgba(0,0,0,.3)}
.cmdk[open]{display:flex;flex-direction:column}
.cmdk::backdrop{background:rgba(0,0,0,.5)}
.cmdk-input{box-sizing:border-box;width:100%;font:inherit;font-size:1.0625rem;padding:.9rem 1rem;border:0;border-bottom:1px solid var(--line,#ddd);background:transparent;color:inherit;outline:none}
.cmdk-input::placeholder{color:var(--muted,#555);opacity:1}
.cmdk-list{list-style:none;margin:0;padding:.375rem;overflow-y:auto;flex:1;min-height:0}
.cmdk-item{display:flex;align-items:center;gap:.75rem;padding:.45rem .625rem;border-left:2px solid transparent;cursor:pointer}
.cmdk-item[aria-selected=true]{background:var(--hover,#f0f0f0);border-left-color:var(--accent,#111)}
.cmdk-text{flex:1;min-width:0}
.cmdk-title,.cmdk-desc{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cmdk-desc{font-size:.8125rem;color:var(--muted,#555)}
.cmdk-tag{flex:none;font-size:.75rem;font-style:italic;color:var(--muted,#555)}
.cmdk-item[aria-selected=true] .cmdk-tag{color:var(--accent,#111)}
.cmdk-empty{padding:1rem .625rem;font-style:italic;color:var(--muted,#555)}
.cmdk-foot{display:flex;gap:1rem;margin:0;padding:.5rem 1rem;border-top:1px solid var(--line,#ddd);font-size:.75rem;color:var(--muted,#555)}
.cmdk-foot kbd{margin-right:.2rem}
@media (max-width:30rem){.cmdk{margin-top:1rem}.cmdk-foot{display:none}}
@media (prefers-reduced-motion:no-preference){.cmdk[open]{animation:cmdk-in .14s ease-out}}
@keyframes cmdk-in{from{opacity:0;transform:translateY(-.25rem)}}
`;
  const style = d.createElement('style');
  style.textContent = css;
  d.head.append(style);

  const dialog = d.createElement('dialog');
  dialog.className = 'cmdk';
  dialog.setAttribute('aria-label', 'Search this site');
  dialog.innerHTML =
    '<input class="cmdk-input" type="text" placeholder="Search pages and commands…" autocomplete="off" spellcheck="false"' +
    ' role="combobox" aria-expanded="true" aria-controls="cmdk-list" aria-autocomplete="list">' +
    '<ul class="cmdk-list" id="cmdk-list" role="listbox" aria-label="Results"></ul>' +
    '<p class="cmdk-foot"><span><kbd>↑</kbd><kbd>↓</kbd>move</span><span><kbd>↵</kbd>open</span><span><kbd>esc</kbd>close</span></p>';
  d.body.append(dialog);
  const input = dialog.querySelector('.cmdk-input');
  const list = dialog.querySelector('.cmdk-list');

  let pages = null; // null until the index has loaded
  let loading = null;
  let results = [];
  let active = 0;
  let lastFocus = null;

  function loadIndex() {
    if (!loading) {
      loading = fetch('/search-index.json', { cache: 'no-cache' })
        .then((r) => (r.ok ? r.json() : { pages: [] }))
        .then((j) => { pages = Array.isArray(j.pages) ? j.pages : []; })
        .catch(() => { pages = []; })
        .then(() => { if (dialog.open) render(); });
    }
    return loading;
  }

  /* ---------- theme ---------- */
  const systemTheme = () => (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  function setTheme(t) {
    if (t) root.dataset.theme = t;
    else delete root.dataset.theme;
    try {
      if (t) localStorage.setItem(THEME_KEY, t);
      else localStorage.removeItem(THEME_KEY);
    } catch (e) { /* storage blocked: theme still applies for this page view */ }
  }
  function themeCommands() {
    const next = (root.dataset.theme || systemTheme()) === 'dark' ? 'light' : 'dark';
    const cmds = [{ group: 'Theme', title: `Switch to ${next} theme`, keywords: 'theme dark light mode toggle appearance', run: () => setTheme(next) }];
    if (root.dataset.theme) {
      cmds.push({ group: 'Theme', title: 'Use system theme', keywords: 'theme auto system default dark light mode', run: () => setTheme(null) });
    }
    return cmds;
  }

  /* ---------- search ---------- */
  function candidates() {
    const p = (pages || []).map((x) => ({
      group: SECTIONS[x.section] || 'Page',
      title: x.title || x.url,
      desc: x.description || '',
      url: x.url,
    }));
    return LINKS.concat(p, themeCommands());
  }
  function score(item, terms) {
    const title = item.title.toLowerCase();
    const hay = [title, item.desc, item.keywords, item.url, item.group].join(' ').toLowerCase();
    let s = 0;
    for (const t of terms) {
      const i = title.indexOf(t);
      if (i === 0) s += 3;
      else if (i > 0) s += 2;
      else if (hay.includes(t)) s += 1;
      else return -1;
    }
    return s;
  }
  function search(q) {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const all = candidates();
    if (!terms.length) return all;
    return all
      .map((it, i) => ({ it, i, s: score(it, terms) }))
      .filter((x) => x.s >= 0)
      .sort((a, b) => b.s - a.s || a.i - b.i)
      .map((x) => x.it);
  }

  /* ---------- rendering ---------- */
  function el(tag, cls, text) {
    const e = d.createElement(tag);
    if (cls) e.className = cls;
    if (text) e.textContent = text;
    return e;
  }
  function render() {
    results = search(input.value).slice(0, 50);
    if (active >= results.length) active = Math.max(0, results.length - 1);
    list.replaceChildren();
    if (!results.length) {
      list.append(el('li', 'cmdk-empty', pages === null ? 'Loading…' : 'No matches.'));
      input.removeAttribute('aria-activedescendant');
      return;
    }
    results.forEach((it, i) => {
      const li = el('li', 'cmdk-item');
      li.id = 'cmdk-opt-' + i;
      li.setAttribute('role', 'option');
      li.setAttribute('aria-selected', 'false');
      const text = el('span', 'cmdk-text');
      text.append(el('span', 'cmdk-title', it.title));
      if (it.desc) text.append(el('span', 'cmdk-desc', it.desc));
      li.append(text, el('span', 'cmdk-tag', it.group));
      li.addEventListener('click', (e) => activate(it, e.metaKey || e.ctrlKey));
      li.addEventListener('pointermove', () => { if (active !== i) setActive(i, false); });
      list.append(li);
    });
    setActive(active, true);
  }
  function setActive(i, scroll) {
    const prev = list.querySelector('[aria-selected="true"]');
    if (prev) prev.setAttribute('aria-selected', 'false');
    active = i;
    const opt = d.getElementById('cmdk-opt-' + i);
    if (!opt) return;
    opt.setAttribute('aria-selected', 'true');
    input.setAttribute('aria-activedescendant', opt.id);
    if (scroll) opt.scrollIntoView({ block: 'nearest' });
  }

  /* ---------- actions ---------- */
  function activate(it, newTab) {
    if (!it) return;
    close();
    if (it.run) { it.run(); return; }
    const external = new URL(it.url, location.href).origin !== location.origin;
    if (newTab || external) window.open(it.url, '_blank', 'noopener');
    else location.href = it.url;
  }
  function open() {
    if (dialog.open) return;
    lastFocus = d.activeElement;
    input.value = '';
    active = 0;
    loadIndex();
    render();
    dialog.showModal();
    input.focus();
  }
  function close() {
    if (dialog.open) dialog.close();
  }
  const isTyping = (t) => t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName));

  dialog.addEventListener('close', () => { if (lastFocus && lastFocus.focus) lastFocus.focus(); });
  dialog.addEventListener('click', (e) => { if (e.target === dialog) close(); }); // backdrop
  input.addEventListener('input', () => { active = 0; render(); });
  input.addEventListener('keydown', (e) => {
    if (e.isComposing) return;
    const n = results.length;
    if (e.key === 'ArrowDown') { e.preventDefault(); if (n) setActive((active + 1) % n, true); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); if (n) setActive((active - 1 + n) % n, true); }
    else if (e.key === 'Enter') { e.preventDefault(); activate(results[active], e.metaKey || e.ctrlKey); }
  });
  d.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && !e.altKey && !e.shiftKey && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      if (dialog.open) close(); else open();
    } else if (e.key === '/' && !dialog.open && !e.metaKey && !e.ctrlKey && !e.altKey && !isTyping(e.target)) {
      e.preventDefault();
      open();
    }
  });

  d.querySelectorAll('[data-cmdk-open]').forEach((b) => {
    b.addEventListener('click', open);
    const k = b.querySelector('kbd');
    if (k) k.textContent = isMac ? '⌘K' : 'Ctrl K';
  });
  root.classList.add('cmdk-ready');
})();
